sysevent_script_action.script:
// DEVELOPMENT AID -- see the `Start Sync` UI Action. Remove both, and the Event Registry entry,
// before this ships.
//
// event.parm1 is the Illumio scheduled job sys_id. process() reads the PCE Configuration and the
// job owner off that record, so nothing else has to ride on the event.
var autoSync = new IllumioAutoSyncWithPCE();
autoSync.process(event.parm1);
